# federation-record-common.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/federation-record-common.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "delivery_id": {
      "pattern": "^dlv-[A-Za-z0-9][A-Za-z0-9._-]*$",
      "type": "string"
    },
    "durable_record": {
      "additionalProperties": false,
      "properties": {
        "commit_before_ack": {
          "const": true
        },
        "committed_at": {
          "format": "date-time",
          "type": "string"
        },
        "key": {
          "minLength": 1,
          "type": "string"
        },
        "revision": {
          "minimum": 1,
          "type": "integer"
        }
      },
      "required": [
        "key",
        "revision",
        "committed_at",
        "commit_before_ack"
      ],
      "type": "object"
    },
    "effective_local_authority": {
      "additionalProperties": false,
      "properties": {
        "actor": {
          "minLength": 1,
          "type": "string"
        },
        "authority_class": {
          "enum": [
            "none",
            "peer_scoped_request",
            "controller_mediated_write"
          ]
        },
        "grant_id": {
          "type": [
            "string",
            "null"
          ]
        },
        "issuer": {
          "enum": [
            "none",
            "local_controller",
            "local_vp"
          ]
        },
        "scope": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "authority_class",
        "actor",
        "scope",
        "issuer",
        "grant_id"
      ],
      "type": "object"
    },
    "mapped_local_actor": {
      "pattern": "^peer:[a-z][a-z0-9-]*$",
      "type": "string"
    },
    "peer_identity": {
      "additionalProperties": false,
      "properties": {
        "auth_method": {
          "enum": [
            "mtls",
            "signed_token"
          ]
        },
        "auth_result": {
          "enum": [
            "authenticated",
            "failed",
            "expired",
            "malformed"
          ]
        },
        "authenticated_principal": {
          "pattern": "^crier:[a-z][a-z0-9-]*$",
          "type": "string"
        },
        "peer_id": {
          "pattern": "^[a-z][a-z0-9-]*$",
          "type": "string"
        }
      },
      "required": [
        "peer_id",
        "authenticated_principal",
        "auth_method",
        "auth_result"
      ],
      "type": "object"
    },
    "provenance": {
      "additionalProperties": false,
      "properties": {
        "origin": {
          "const": "peer"
        },
        "peer_id": {
          "pattern": "^[a-z][a-z0-9-]*$",
          "type": "string"
        },
        "peer_request_id": {
          "pattern": "^pr-[A-Za-z0-9][A-Za-z0-9._-]*$",
          "type": "string"
        },
        "source_system": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "origin",
        "source_system",
        "peer_id",
        "peer_request_id"
      ],
      "type": "object"
    },
    "record_id": {
      "pattern": "^/chd/federation/[a-z0-9][a-z0-9._/-]*$",
      "type": "string"
    },
    "record_type": {
      "type": "string"
    },
    "schema_version": {
      "const": 1
    },
    "service_identity": {
      "additionalProperties": false,
      "properties": {
        "authenticated_as": {
          "const": "crier-bridge-service"
        },
        "authority_class": {
          "const": "bridge_transport_only"
        },
        "credential_ref": {
          "minLength": 1,
          "type": "string"
        },
        "service_id": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "service_id",
        "authenticated_as",
        "credential_ref",
        "authority_class"
      ],
      "type": "object"
    },
    "transport_credential_authority": {
      "const": "none"
    }
  },
  "required": [
    "schema_version",
    "record_type",
    "record_id",
    "service_identity",
    "peer_identity",
    "mapped_local_actor",
    "effective_local_authority",
    "transport_credential_authority",
    "delivery_id",
    "provenance",
    "durable_record"
  ],
  "title": "Common Crier federation record fields",
  "type": "object"
}
```
